INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('friends', 1, 'What is the most unhinged thing in your search history from this past week?', 'Cual es la cosa mas loca en tu historial de busqueda de esta semana pasada?'),
('friends', 1, 'If your group chat got turned into a sitcom, who would be the breakout character?', 'Si tu chat grupal se convirtiera en una serie, quien seria el personaje estrella?'),
('friends', 1, 'What completely useless skill have you accidentally mastered this year?', 'Que habilidad completamente inutil has dominado por accidente este ano?'),
('friends', 1, 'If you had to assign each of us a signature drink based on our personality, what is mine?', 'Si tuvieras que asignarnos a cada uno una bebida segun nuestra personalidad, cual seria la mia?'),
('friends', 1, 'What is the pettiest hill you would gladly die on right now?', 'Cual es la tonteria mas pequena por la que defenderias tu opinion hasta el final ahora mismo?'),
('friends', 1, 'If your phone died tomorrow with no backup, which lost photo would you grieve the most?', 'Si tu telefono muriera manana sin respaldo, que foto perdida llorarias mas?'),
('friends', 1, 'What is the dumbest thing you have spent more than ten dollars on recently?', 'Cual es la cosa mas tonta en la que has gastado mas de diez dolares recientemente?'),
('friends', 1, 'If someone made a Spotify playlist titled exactly your name, what would track one be?', 'Si alguien hiciera una lista de Spotify con tu nombre exacto, cual seria la primera cancion?'),
('friends', 1, 'What is a snack pairing you defend with your whole chest that other people find weird?', 'Cual es una combinacion de snacks que defiendes con toda tu alma y otros encuentran rara?'),
('friends', 1, 'If we were stranded together for a weekend with no signal, who would lose their mind first?', 'Si estuvieramos varados juntos un fin de semana sin senal, quien perderia la cabeza primero?'),
('friends', 1, 'What is your most chaotic recent purchase that genuinely surprised you when it arrived?', 'Cual es tu compra reciente mas caotica que te sorprendio cuando llego?'),
('friends', 1, 'If your mood today were a weather forecast, what would the headline say?', 'Si tu estado de animo de hoy fuera un pronostico del tiempo, que diria el titular?'),
('friends', 1, 'What is a tiny daily ritual of yours that nobody notices but you would defend forever?', 'Cual es un pequeno ritual diario tuyo que nadie nota pero defenderias para siempre?'),
('friends', 1, 'If we swapped lives for one day, what would be the first thing you would change about mine?', 'Si intercambiaramos vidas por un dia, que seria lo primero que cambiarias de la mia?'),
('friends', 1, 'What is the most overrated thing in pop culture right now, in your honest opinion?', 'Cual es la cosa mas sobrevalorada de la cultura pop ahora mismo, en tu honesta opinion?'),
('friends', 1, 'If you had to name the vibe of our friendship using only one made-up word, what is it?', 'Si tuvieras que nombrar la vibra de nuestra amistad con una sola palabra inventada, cual seria?'),
('friends', 1, 'What is something you do alone that brings you absurd levels of joy?', 'Que haces a solas que te trae niveles absurdos de alegria?'),
('friends', 1, 'If you had to pitch a reality show starring you and one friend in this room, what is the premise?', 'Si tuvieras que proponer un reality show con tigo y un amigo en esta sala, cual seria la premisa?'),
('friends', 1, 'What is the most unexpected thing you have become obsessed with this past month?', 'Cual es la cosa mas inesperada con la que te has obsesionado este mes pasado?'),
('friends', 1, 'If a stranger followed you around taking notes for a day, what would be the most baffling entry?', 'Si un extrano te siguiera tomando notas todo el dia, cual seria la entrada mas desconcertante?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('friends', 2, 'What is something about your personality you have grown to like that you used to try to hide?', 'Que aspecto de tu personalidad has aprendido a gustarte que antes intentabas esconder?'),
('friends', 2, 'When did you last realize a friendship had quietly become more important than you noticed?', 'Cuando te diste cuenta por ultima vez de que una amistad se habia vuelto mas importante de lo que notaste?'),
('friends', 2, 'What is a compliment someone gave you recently that you keep replaying in your head?', 'Cual es un cumplido que alguien te dio recientemente que sigues repitiendo en tu mente?'),
('friends', 2, 'What is something you have become more patient about that you used to fight constantly?', 'En que has aprendido a ser mas paciente que antes peleabas constantemente?'),
('friends', 2, 'When was the last time you felt genuinely proud of yourself for something small?', 'Cuando fue la ultima vez que te sentiste genuinamente orgulloso de ti por algo pequeno?'),
('friends', 2, 'What is a habit you picked up recently that has quietly changed your week for the better?', 'Que habito has adoptado recientemente que ha mejorado tu semana en silencio?'),
('friends', 2, 'When did you first notice that you and I had become real friends and not just people who knew each other?', 'Cuando notaste por primera vez que tu y yo nos habiamos convertido en amigos de verdad y no solo conocidos?'),
('friends', 2, 'What is a piece of music or a movie that hits you completely differently now than it used to?', 'Que pieza de musica o pelicula te llega completamente diferente ahora que antes?'),
('friends', 2, 'What is a small kindness someone has done for you lately that you have not stopped thinking about?', 'Que pequena amabilidad ha tenido alguien contigo ultimamente en la que no has dejado de pensar?'),
('friends', 2, 'What is something you have changed your mind about this year that surprised even you?', 'En que has cambiado de opinion este ano que te sorprendio incluso a ti?'),
('friends', 2, 'When did you last laugh so hard with someone that you remembered exactly why you love them?', 'Cuando fue la ultima vez que reiste tanto con alguien que recordaste exactamente porque lo amas?'),
('friends', 2, 'What is a quality you admire in one of us that you are quietly working to grow in yourself?', 'Que cualidad admiras en uno de nosotros que estas trabajando en silencio para cultivar en ti?'),
('friends', 2, 'What is a memory from our friendship that you find yourself reaching for when you need a smile?', 'Que recuerdo de nuestra amistad buscas cuando necesitas una sonrisa?'),
('friends', 2, 'What is something you used to chase that you no longer need, and what changed?', 'Que solias perseguir que ya no necesitas, y que cambio?'),
('friends', 2, 'What is a song that always makes you think of one of us, and who is it about?', 'Que cancion siempre te hace pensar en uno de nosotros, y de quien es?'),
('friends', 2, 'What is the most thoughtful gift you have ever received from a friend, big or small?', 'Cual es el regalo mas considerado que has recibido de un amigo, grande o pequeno?'),
('friends', 2, 'What is a fear you used to carry that you have made peace with this year?', 'Que miedo solias cargar con el que has hecho las paces este ano?'),
('friends', 2, 'When did you last feel completely at home in a room, and who else was in it?', 'Cuando te sentiste por ultima vez completamente en casa en una sala, y quien mas estaba ahi?'),
('friends', 2, 'What is something one of us does that you find quietly beautiful even if you have never said it?', 'Que hace uno de nosotros que encuentras silenciosamente hermoso aunque nunca lo hayas dicho?'),
('friends', 2, 'What is a tiny tradition between us that you would be devastated to lose?', 'Cual es una pequena tradicion entre nosotros que te devastaria perder?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('friends', 3, 'What is something you are still learning about how to be a good friend?', 'Que sigues aprendiendo sobre como ser un buen amigo?'),
('friends', 3, 'What is a kindness you did recently that nobody knew was you?', 'Que amabilidad hiciste recientemente que nadie supo que eras tu?'),
('friends', 3, 'When have you stayed in a conversation that was hard because the person needed you to?', 'Cuando te has quedado en una conversacion dificil porque la persona te necesitaba?'),
('friends', 3, 'What is an apology you have been carrying that you have not yet offered out loud?', 'Que disculpa has estado cargando que no has ofrecido en voz alta?'),
('friends', 3, 'When did you last realize you had been holding a grudge about something small?', 'Cuando te diste cuenta por ultima vez de que guardabas rencor por algo pequeno?'),
('friends', 3, 'What is something you have done in the past year that took more courage than anyone knows?', 'Que has hecho en el ultimo ano que requirio mas valor del que nadie sabe?'),
('friends', 3, 'When have you noticed yourself becoming someone your younger self would have looked up to?', 'Cuando te has notado convirtiendote en alguien que tu yo mas joven habria admirado?'),
('friends', 3, 'What is a part of growing up that has been harder than you expected this year?', 'Que parte de crecer ha sido mas dificil de lo que esperabas este ano?'),
('friends', 3, 'When have you forgiven yourself for something you were carrying longer than you should have?', 'Cuando te has perdonado a ti mismo por algo que cargabas mas tiempo del que debias?'),
('friends', 3, 'What is something true about you right now that you have not figured out how to put into words?', 'Que es algo verdadero sobre ti ahora mismo que no has descubierto como poner en palabras?'),
('friends', 3, 'What is a question you have been quietly asking yourself lately?', 'Que pregunta te has estado haciendo en silencio ultimamente?'),
('friends', 3, 'When did you last feel completely understood by someone, and what did they do that mattered?', 'Cuando te sentiste por ultima vez completamente entendido por alguien, y que hizo que importo?'),
('friends', 3, 'What is something a friend taught you about yourself that you would never have seen alone?', 'Que te ensenó un amigo sobre ti mismo que nunca habrias visto solo?'),
('friends', 3, 'What is a moment in our friendship that quietly shifted how you see yourself?', 'Que momento en nuestra amistad cambio silenciosamente como te ves a ti mismo?'),
('friends', 3, 'When have you let someone down recently in a way that has stayed with you?', 'Cuando has fallado a alguien recientemente de una manera que se ha quedado contigo?'),
('friends', 3, 'What is something you wish you had said the last time you sat with someone you love?', 'Que desearias haber dicho la ultima vez que estuviste con alguien que amas?'),
('friends', 3, 'What is a piece of yourself you are trying to be more generous with this year?', 'Que parte de ti estas tratando de ser mas generoso con ella este ano?'),
('friends', 3, 'When did you last cry in a way that felt like a relief instead of a defeat?', 'Cuando lloraste por ultima vez de una manera que se sintio como alivio en lugar de derrota?'),
('friends', 3, 'What is something you used to need from friends that you have learned to give yourself?', 'Que solias necesitar de amigos que has aprendido a darte a ti mismo?'),
('friends', 3, 'When have you watched a friend become someone new, and how did it change you?', 'Cuando has visto a un amigo convertirse en alguien nuevo, y como te cambio?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('friends', 4, 'What is the truth about your life right now that you almost never say out loud?', 'Cual es la verdad sobre tu vida ahora mismo que casi nunca dices en voz alta?'),
('friends', 4, 'What is a fear about our friendship that you have never told me?', 'Cual es un miedo sobre nuestra amistad que nunca me has dicho?'),
('friends', 4, 'When was the last time you felt completely alone in a room full of people who love you?', 'Cuando fue la ultima vez que te sentiste completamente solo en una sala llena de gente que te ama?'),
('friends', 4, 'What is something you wish you could ask for from your friends but you do not know how?', 'Que desearias poder pedirle a tus amigos pero no sabes como?'),
('friends', 4, 'What is a way you have changed recently that scares you a little?', 'En que has cambiado recientemente que te asusta un poco?'),
('friends', 4, 'What is a part of yourself you are still learning how to introduce to the people you love?', 'Que parte de ti sigues aprendiendo como presentar a la gente que amas?'),
('friends', 4, 'What is the version of you that only your closest people get to see?', 'Cual es la version de ti que solo tus personas mas cercanas pueden ver?'),
('friends', 4, 'What is something you have been pretending is fine that actually is not?', 'Que has estado fingiendo que esta bien que en realidad no lo esta?'),
('friends', 4, 'When have you felt jealousy toward a friend, and what did it teach you about yourself?', 'Cuando has sentido celos hacia un amigo, y que te enseno sobre ti mismo?'),
('friends', 4, 'What is a wound from earlier in life that still shows up in how you show up for others?', 'Que herida de antes en la vida sigue apareciendo en como te presentas para otros?'),
('friends', 4, 'What is something you needed your friends to do for you years ago that you can finally name now?', 'Que necesitabas que tus amigos hicieran por ti hace anos que finalmente puedes nombrar ahora?'),
('friends', 4, 'When have you felt like the person everyone leans on but no one checks on?', 'Cuando te has sentido como la persona en quien todos se apoyan pero nadie se preocupa por ti?'),
('friends', 4, 'What is a confession you have been carrying that would only feel safe with the people in this room?', 'Que confesion has estado cargando que solo se sentiria segura con la gente en esta sala?'),
('friends', 4, 'What is the most honest thing you could tell us right now about how you are actually doing?', 'Cual es la cosa mas honesta que podrias decirnos ahora mismo sobre como estas realmente?'),
('friends', 4, 'When did you last let yourself be loved exactly as you are, and who did the loving?', 'Cuando te dejaste amar por ultima vez exactamente como eres, y quien hizo el amar?'),
('friends', 4, 'What is something you used to need to prove that you no longer feel like proving?', 'Que solias necesitar probar que ya no sientes la necesidad de probar?'),
('friends', 4, 'What is a question you have been afraid to ask one of us in this room?', 'Que pregunta has tenido miedo de hacerle a uno de nosotros en esta sala?'),
('friends', 4, 'When have you felt yourself drifting from someone and chosen to row back, and what made you turn around?', 'Cuando te has sentido alejandote de alguien y elegiste regresar, y que te hizo voltear?'),
('friends', 4, 'What is a piece of grief you carry that the people around you would never guess?', 'Que pieza de duelo cargas que la gente a tu alrededor nunca adivinaria?'),
('friends', 4, 'What is something tender you have been wanting to say to one of us tonight?', 'Que cosa tierna has querido decirle a uno de nosotros esta noche?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('friends', 5, 'What is the quiet truth about this friendship that you hope we never lose sight of?', 'Cual es la verdad silenciosa sobre esta amistad que esperas que nunca perdamos de vista?'),
('friends', 5, 'What is one specific thing you would want each person in this room to know they gave you?', 'Cual es una cosa especifica que querrias que cada persona en esta sala supiera que te dio?'),
('friends', 5, 'If our friendship were the only one you got to carry through your whole life, what would it have taught you?', 'Si nuestra amistad fuera la unica que pudieras cargar toda la vida, que te habria ensenado?'),
('friends', 5, 'What is the version of yourself you became because we love you that you would not have found alone?', 'Cual es la version de ti que te volviste porque te amamos que no habrias encontrado solo?'),
('friends', 5, 'What is a goodbye you carry from earlier in life that quietly shapes how you love now?', 'Que despedida cargas de antes en la vida que silenciosamente forma como amas ahora?'),
('friends', 5, 'What is something you survived that you no longer need to hide from the people who love you?', 'Que sobreviviste que ya no necesitas esconder de la gente que te ama?'),
('friends', 5, 'What is a kind of love you stopped expecting that this friendship has quietly given back to you?', 'Que tipo de amor dejaste de esperar que esta amistad te ha devuelto silenciosamente?'),
('friends', 5, 'If you had to write a single sentence on the wall about what we mean to you, what would it say?', 'Si tuvieras que escribir una sola oracion en la pared sobre lo que significamos para ti, que diria?'),
('friends', 5, 'What is the bravest thing you have done in the last year that almost no one knows about?', 'Cual es la cosa mas valiente que has hecho el ultimo ano que casi nadie sabe?'),
('friends', 5, 'What is a hard truth you had to accept about yourself that ended up being a gift?', 'Que verdad dificil tuviste que aceptar sobre ti mismo que termino siendo un regalo?'),
('friends', 5, 'What is a part of you that you grieved having to leave behind in order to become who you are now?', 'Que parte de ti lloraste tener que dejar atras para convertirte en quien eres ahora?'),
('friends', 5, 'What is the most generous thing you have ever done for someone who could never repay you?', 'Cual es la cosa mas generosa que has hecho por alguien que nunca podria pagarte?'),
('friends', 5, 'What is a memory you would want us to tell at your eightieth birthday, when you can no longer tell it yourself?', 'Que recuerdo querrias que contaramos en tu cumpleanos numero ochenta, cuando ya no puedas contarlo tu mismo?'),
('friends', 5, 'What is something you want me to remember about who you are right now, in case you change in ways neither of us expects?', 'Que quieres que recuerde sobre quien eres ahora mismo, por si cambias de maneras que ninguno de los dos espera?'),
('friends', 5, 'What is a love you lost that taught you how to love the rest of us better?', 'Que amor perdiste que te enseno a amarnos mejor a los demas?'),
('friends', 5, 'When did you first realize that being known by us was different from being loved at all, and how did it change you?', 'Cuando te diste cuenta por primera vez de que ser conocido por nosotros era diferente a ser amado en general, y como te cambio?'),
('friends', 5, 'What is the version of your future you most quietly hope for, and where do you see us in it?', 'Cual es la version de tu futuro que mas silenciosamente esperas, y donde nos ves en ella?'),
('friends', 5, 'What is the hardest year you have lived through, and what is the unexpected gift it left behind?', 'Cual es el ano mas dificil que has vivido, y cual es el regalo inesperado que dejo atras?'),
('friends', 5, 'What is one thing you want each of us to forgive you for, even if we already have?', 'Que cosa quieres que cada uno de nosotros te perdone, incluso si ya lo hicimos?'),
('friends', 5, 'If we never sat together like this again, what is the one thing you would need to make sure you said tonight?', 'Si nunca nos sentaramos juntos asi de nuevo, cual es la unica cosa que necesitarias asegurarte de decir esta noche?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('family', 1, 'What is a phrase one of our parents says so often we could lip-sync it?', 'Cual es una frase que uno de nuestros padres dice tanto que podriamos imitarla con los labios?'),
('family', 1, 'What is the most chaotic holiday meal we have ever shared, and what made it legendary?', 'Cual es la comida festiva mas caotica que hemos compartido, y que la hizo legendaria?'),
('family', 1, 'What is the family inside joke that nobody outside this family could ever explain?', 'Cual es la broma familiar interna que nadie fuera de esta familia podria explicar?'),
('family', 1, 'What is a household chore you would happily go to court to never do again?', 'Cual es un quehacer del hogar que felizmente iras a corte para nunca hacer de nuevo?'),
('family', 1, 'If our family were a sitcom, what would the laugh track absolutely lose it over?', 'Si nuestra familia fuera una serie, de que se reiria a carcajadas la pista de risas?'),
('family', 1, 'What is a piece of furniture in our house that has survived way too many catastrophes?', 'Que mueble en nuestra casa ha sobrevivido demasiadas catastrofes?'),
('family', 1, 'What is the most embarrassing photo of you that someone in this family has framed somewhere?', 'Cual es la foto mas vergonzosa de ti que alguien en esta familia tiene enmarcada en algun lugar?'),
('family', 1, 'What is the dish you can cook better than anyone in this family is willing to admit?', 'Cual es el platillo que cocinas mejor que cualquiera en esta familia esta dispuesto a admitir?'),
('family', 1, 'What is the one road trip our family talks about more than any other, and why does it stick?', 'Cual es el unico viaje en carretera del que nuestra familia habla mas que cualquier otro, y porque se queda en la memoria?'),
('family', 1, 'What is your favorite small ritual we do as a family that we have never given a name?', 'Cual es tu pequeno ritual favorito que hacemos como familia al que nunca le hemos dado un nombre?'),
('family', 1, 'What is a song from childhood that instantly transports you back to our house?', 'Que cancion de la infancia te transporta instantaneamente de regreso a nuestra casa?'),
('family', 1, 'What is the most surprising hobby anyone in this family has secretly picked up lately?', 'Cual es el pasatiempo mas sorprendente que alguien en esta familia ha adoptado en secreto ultimamente?'),
('family', 1, 'What is a smell that always means home to you, even if you cannot place exactly why?', 'Que olor siempre significa hogar para ti, aunque no puedas ubicar exactamente por que?'),
('family', 1, 'What is the most ridiculous argument we have ever had as a family that we now laugh about?', 'Cual es la discusion mas ridicula que hemos tenido como familia de la que ahora nos reimos?'),
('family', 1, 'What is the strangest superstition someone in our family genuinely believes in?', 'Cual es la supersticion mas rara en la que alguien en nuestra familia genuinamente cree?'),
('family', 1, 'What is your go-to comfort food from when we were kids that you still crave?', 'Cual es tu comida reconfortante favorita de cuando eramos ninos que todavia se te antoja?'),
('family', 1, 'What is the funniest nickname you have ever been called by someone in this family?', 'Cual es el apodo mas chistoso que alguien en esta familia te haya puesto?'),
('family', 1, 'What is something one of us does that is so on-brand it should be in the dictionary?', 'Que hace uno de nosotros que es tan caracteristico que deberia estar en el diccionario?'),
('family', 1, 'What is a household rule we grew up with that you still cannot bring yourself to break?', 'Que regla del hogar con la que crecimos todavia no puedes romper?'),
('family', 1, 'What is the most absurd thing our family has ever insisted is normal?', 'Cual es la cosa mas absurda que nuestra familia ha insistido en que es normal?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('family', 2, 'What is a trait you got from one of our parents that you used to resist and now appreciate?', 'Cual es un rasgo que sacaste de uno de nuestros padres al que solias resistirte y ahora aprecias?'),
('family', 2, 'When did you first realize one of your siblings was becoming an actual adult?', 'Cuando te diste cuenta por primera vez de que uno de tus hermanos se estaba convirtiendo en un adulto de verdad?'),
('family', 2, 'What is something you used to find embarrassing about our family that you now love?', 'Que solias encontrar vergonzoso de nuestra familia que ahora amas?'),
('family', 2, 'What is a recipe or skill you wish someone had taught you while we still had the chance?', 'Que receta o habilidad desearias que alguien te hubiera ensenado cuando todavia teniamos la oportunidad?'),
('family', 2, 'What is a memory from a family gathering that you replay in your head when you need to feel safe?', 'Que recuerdo de una reunion familiar repites en tu mente cuando necesitas sentirte seguro?'),
('family', 2, 'When did one of us teach you something just by the way they handled something hard?', 'Cuando uno de nosotros te enseno algo solo por la manera en que manejo algo dificil?'),
('family', 2, 'What is a story about an older relative you wish you had asked more questions about?', 'Que historia sobre un pariente mayor desearias haber preguntado mas sobre ella?'),
('family', 2, 'What is something you have become softer about as you have gotten older in this family?', 'En que te has vuelto mas suave a medida que has crecido en esta familia?'),
('family', 2, 'What is a small moment with one of us that you remember more clearly than huge events?', 'Que pequeno momento con uno de nosotros recuerdas mas claramente que eventos enormes?'),
('family', 2, 'What is something a family member did for you when you were younger that you only now understand?', 'Que hizo un miembro de la familia por ti cuando eras mas joven que solo ahora entiendes?'),
('family', 2, 'When have you watched a family member do something brave that you do not think they got enough credit for?', 'Cuando has visto a un miembro de la familia hacer algo valiente por lo que crees que no recibio suficiente credito?'),
('family', 2, 'What is a tradition you secretly hope we keep alive when our parents are no longer the ones leading it?', 'Que tradicion esperas en secreto que mantengamos viva cuando nuestros padres ya no sean los que la lideren?'),
('family', 2, 'What is a side of one of us you have only recently started to notice?', 'Que lado de uno de nosotros solo recientemente has empezado a notar?'),
('family', 2, 'What is something you have learned about your parents now that you see them as people, not just parents?', 'Que has aprendido sobre tus padres ahora que los ves como personas, no solo como padres?'),
('family', 2, 'When did you first realize you were starting to sound like one of our parents in a way you actually liked?', 'Cuando te diste cuenta por primera vez de que estabas empezando a sonar como uno de nuestros padres de una manera que en realidad te gusto?'),
('family', 2, 'What is a sibling rivalry from years ago that you can finally laugh about now?', 'Que rivalidad entre hermanos de hace anos finalmente puedes reir ahora?'),
('family', 2, 'What is one thing you wish our family did more often, even if it would feel awkward at first?', 'Que cosa desearias que nuestra familia hiciera mas a menudo, aunque al principio se sintiera incomodo?'),
('family', 2, 'What is the most unexpected way you see our family in your daily life when you are far from us?', 'Cual es la manera mas inesperada en que ves a nuestra familia en tu vida diaria cuando estas lejos de nosotros?'),
('family', 2, 'What is a part of yourself that only this family has ever really gotten to see?', 'Que parte de ti que solo esta familia realmente ha podido ver?'),
('family', 2, 'When did you last feel proud of being part of this family in a quiet way you have never said out loud?', 'Cuando te sentiste orgulloso por ultima vez de ser parte de esta familia de una manera silenciosa que nunca has dicho en voz alta?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('family', 3, 'What is something you finally understand about a family member now that you are older?', 'Que entiendes finalmente sobre un miembro de la familia ahora que eres mayor?'),
('family', 3, 'When did you first feel like a peer to your parents instead of a kid?', 'Cuando te sentiste por primera vez como un igual a tus padres en lugar de un nino?'),
('family', 3, 'What is a hard conversation you wish our family had braver about years ago?', 'Que conversacion dificil desearias que nuestra familia hubiera tenido mas valiente hace anos?'),
('family', 3, 'What is something you have been quietly working on healing in yourself that started in this family?', 'Que has estado trabajando en silencio para sanar en ti que comenzo en esta familia?'),
('family', 3, 'When was the last time a family member surprised you with how much they had grown?', 'Cuando fue la ultima vez que un miembro de la familia te sorprendio con cuanto habia crecido?'),
('family', 3, 'What is something you have forgiven a family member for, even if you never told them out loud?', 'Que has perdonado a un miembro de la familia, aunque nunca se lo hayas dicho en voz alta?'),
('family', 3, 'What is a piece of love from our family that you used to take for granted and now do not?', 'Que pieza de amor de nuestra familia solias dar por sentada y ya no?'),
('family', 3, 'When have you watched one of our parents do something that quietly changed how you see them?', 'Cuando has visto a uno de nuestros padres hacer algo que silenciosamente cambio como los ves?'),
('family', 3, 'What is a way you have tried to break a cycle in our family without making a big deal of it?', 'De que manera has tratado de romper un ciclo en nuestra familia sin hacer un gran alboroto?'),
('family', 3, 'What is something one of our parents got right that you only fully appreciate now?', 'Que hizo bien uno de nuestros padres que solo aprecias por completo ahora?'),
('family', 3, 'What is a moment with a family member that quietly changed the direction of your life?', 'Que momento con un miembro de la familia cambio silenciosamente la direccion de tu vida?'),
('family', 3, 'When did you last feel really seen by a sibling, and what did they do?', 'Cuando te sentiste por ultima vez realmente visto por un hermano, y que hizo?'),
('family', 3, 'What is a way you have softened toward a family member who used to drive you wild?', 'De que manera te has suavizado hacia un miembro de la familia que solia volverte loco?'),
('family', 3, 'What is something hard about your life lately that you have not shared with our family yet?', 'Que es algo dificil sobre tu vida ultimamente que aun no has compartido con nuestra familia?'),
('family', 3, 'What is a tradition that has quietly meant more to you each year, even as you got older?', 'Que tradicion ha significado silenciosamente mas para ti cada ano, incluso a medida que envejeciste?'),
('family', 3, 'When did you last feel grateful for being raised by the specific combination of people you were?', 'Cuando te sentiste por ultima vez agradecido por haber sido criado por la combinacion especifica de personas que te crio?'),
('family', 3, 'What is something you used to be ashamed of in this family that you can talk about now?', 'De que solias estar avergonzado en esta familia de lo que puedes hablar ahora?'),
('family', 3, 'When have you watched a family member become softer, and what do you think changed them?', 'Cuando has visto a un miembro de la familia volverse mas suave, y que crees que lo cambio?'),
('family', 3, 'What is a question you wish you had asked a grandparent while you still could?', 'Que pregunta desearias haberle hecho a un abuelo mientras aun podias?'),
('family', 3, 'When have you noticed yourself parenting yourself the way one of our parents could not?', 'Cuando te has notado siendo padre de ti mismo de la manera que uno de nuestros padres no pudo?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('family', 4, 'What is something you needed from this family as a child that you can finally name now?', 'Que necesitabas de esta familia como nino que finalmente puedes nombrar ahora?'),
('family', 4, 'What is a way our family loved you that no one outside this room would understand?', 'De que manera nuestra familia te amo que nadie fuera de esta sala entenderia?'),
('family', 4, 'When have you felt invisible in this family in a way that has stayed with you?', 'Cuando te has sentido invisible en esta familia de una manera que se ha quedado contigo?'),
('family', 4, 'What is something you have grieved about our family that you have never let yourself say out loud?', 'Que has lamentado sobre nuestra familia que nunca te has permitido decir en voz alta?'),
('family', 4, 'What is a question you have wanted to ask one of our parents your whole life and never have?', 'Que pregunta has querido hacerle a uno de nuestros padres toda tu vida y nunca lo has hecho?'),
('family', 4, 'When did you first understand that our parents were carrying something they never put into words?', 'Cuando entendiste por primera vez que nuestros padres cargaban algo que nunca pusieron en palabras?'),
('family', 4, 'What is something you wish one of our siblings would say to you that they never have?', 'Que desearias que uno de nuestros hermanos te dijera que nunca ha dicho?'),
('family', 4, 'What is the moment in this family that broke something quietly inside you, even though you never named it?', 'Cual es el momento en esta familia que rompio algo silenciosamente dentro de ti, aunque nunca lo nombraste?'),
('family', 4, 'What is something you carry that you suspect a parent carried before you?', 'Que cargas que sospechas que un padre cargo antes que tu?'),
('family', 4, 'When have you wanted to be held by a family member and not known how to ask?', 'Cuando has querido que un miembro de la familia te abrazara y no has sabido como pedirlo?'),
('family', 4, 'What is something you have been protecting our family from knowing about your life?', 'Que has estado protegiendo a nuestra familia de saber sobre tu vida?'),
('family', 4, 'What is a kind of love you are still hoping to receive from one of us?', 'Que tipo de amor todavia esperas recibir de uno de nosotros?'),
('family', 4, 'When have you felt yourself becoming a parent to one of our parents, and what was that like?', 'Cuando te has sentido convirtiendote en padre de uno de nuestros padres, y como fue eso?'),
('family', 4, 'What is the part of your story you wish our family had handled with more gentleness?', 'Cual es la parte de tu historia que desearias que nuestra familia hubiera manejado con mas ternura?'),
('family', 4, 'What is a tenderness toward one of us that you have been holding back from showing?', 'Que ternura hacia uno de nosotros has estado conteniendo de mostrar?'),
('family', 4, 'What is something you suspect a family member has been carrying alone for too long?', 'Que sospechas que un miembro de la familia ha estado cargando solo por demasiado tiempo?'),
('family', 4, 'What is a moment in our family where someone needed to be held and was not, and how does it shape you now?', 'Cual es un momento en nuestra familia en el que alguien necesitaba ser abrazado y no lo fue, y como te forma ahora?'),
('family', 4, 'When have you felt closer to a family member after seeing them at their lowest?', 'Cuando te has sentido mas cercano a un miembro de la familia despues de verlo en su peor momento?'),
('family', 4, 'What is the thing you most want our family to be able to talk about that we still cannot quite?', 'Cual es la cosa que mas quieres que nuestra familia pueda hablar que aun no podemos del todo?'),
('family', 4, 'What is something you have stopped pretending to be okay about with this family?', 'Que has dejado de fingir que estas bien con esta familia?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('family', 5, 'What part of who you are did you have to grieve in order to become the person you are now?', 'Que parte de quien eres tuviste que lamentar para convertirte en la persona que eres ahora?'),
('family', 5, 'What is the most important thing you want the next generation of our family to carry forward?', 'Cual es la cosa mas importante que quieres que la proxima generacion de nuestra familia lleve adelante?'),
('family', 5, 'What is a family wound you are quietly trying not to pass down, and what gives you hope you can?', 'Que herida familiar estas tratando silenciosamente de no transmitir, y que te da esperanza de que puedas?'),
('family', 5, 'What is something you have already forgiven that nobody knows you have forgiven?', 'Que ya has perdonado que nadie sabe que has perdonado?'),
('family', 5, 'What is the most surprising kind of love you have come to feel for someone in this family?', 'Cual es el tipo de amor mas sorprendente que has llegado a sentir por alguien en esta familia?'),
('family', 5, 'What is a moment from this family that you would relive exactly as it was, even with what it cost you?', 'Cual es un momento de esta familia que volverias a vivir exactamente como fue, incluso con lo que te costo?'),
('family', 5, 'What is the kind of parent or sibling you most want to be remembered as?', 'Cual es el tipo de padre o hermano por el que mas quieres ser recordado?'),
('family', 5, 'What is the version of our family you most quietly hope we become twenty years from now?', 'Cual es la version de nuestra familia que mas silenciosamente esperas que nos volvamos dentro de veinte anos?'),
('family', 5, 'What is something you only realized you missed about our family after you started a life of your own?', 'Que solo te diste cuenta de que extranabas de nuestra familia despues de empezar tu propia vida?'),
('family', 5, 'What is something you wish you had said to a family member who is no longer with us, or no longer the same?', 'Que desearias haberle dicho a un miembro de la familia que ya no esta con nosotros, o ya no es el mismo?'),
('family', 5, 'What is the gift you wish you could give a younger version of yourself in this house?', 'Cual es el regalo que desearias poder darle a una version mas joven de ti en esta casa?'),
('family', 5, 'What is the hardest year this family lived through together, and what did it leave behind that you are grateful for?', 'Cual es el ano mas dificil que esta familia vivio junta, y que dejo atras por lo que estas agradecido?'),
('family', 5, 'What is something you needed our parents to know that you can finally say tonight?', 'Que necesitabas que nuestros padres supieran que finalmente puedes decir esta noche?'),
('family', 5, 'What is a piece of who you are that you are certain came from being raised in this specific family?', 'Cual es una pieza de quien eres de la que estas seguro que vino de ser criado en esta familia especifica?'),
('family', 5, 'What is the most generous thing you have ever done for a family member that they never knew about?', 'Cual es la cosa mas generosa que has hecho por un miembro de la familia que el nunca supo?'),
('family', 5, 'What is a way you want this family to be able to say goodbye to each other when the time comes?', 'De que manera quieres que esta familia pueda decirse adios cuando llegue el momento?'),
('family', 5, 'What is the love story between any two people in this family that you find most beautiful to witness?', 'Cual es la historia de amor entre dos personas en esta familia que encuentras mas hermosa de presenciar?'),
('family', 5, 'What is something you want me specifically to remember about you after everything else fades?', 'Que quieres que yo especificamente recuerde sobre ti despues de que todo lo demas se desvanezca?'),
('family', 5, 'What is the most honest gratitude you carry for someone in this room that you have never said out loud?', 'Cual es la gratitud mas honesta que cargas por alguien en esta sala que nunca has dicho en voz alta?'),
('family', 5, 'If our family had to be remembered for one single thing across generations, what would you choose for that to be?', 'Si nuestra familia tuviera que ser recordada por una sola cosa a traves de las generaciones, que elegirias para eso?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('lovers', 1, 'What is the smallest thing I do that you find ridiculously attractive?', 'Cual es la cosa mas pequena que hago que encuentras ridiculamente atractiva?'),
('lovers', 1, 'What is the dorkiest thing about me you would never want me to change?', 'Cual es la cosa mas tonta sobre mi que nunca querrias que cambiara?'),
('lovers', 1, 'If we had a tiny restaurant together, what is the one dish neither of us would let off the menu?', 'Si tuvieramos un pequeno restaurante juntos, cual es el unico platillo que ninguno de los dos quitaria del menu?'),
('lovers', 1, 'What is a song that instantly transports you back to early us?', 'Que cancion te transporta instantaneamente al principio de nosotros?'),
('lovers', 1, 'If our life together had a tagline on a movie poster, what would it say?', 'Si nuestra vida juntos tuviera un eslogan en un cartel de pelicula, que diria?'),
('lovers', 1, 'What is the most chaotic shared inside joke we have built that nobody else would understand?', 'Cual es la broma interna mas caotica que hemos construido que nadie mas entenderia?'),
('lovers', 1, 'What is your favorite version of me when I first wake up in the morning?', 'Cual es tu version favorita de mi cuando me despierto en la manana?'),
('lovers', 1, 'If you had to plan the most us date possible with twenty dollars, what is the night?', 'Si tuvieras que planear la cita mas nuestra posible con veinte dolares, cual es la noche?'),
('lovers', 1, 'What is the smell of mine you would recognize anywhere on earth?', 'Cual es el olor mio que reconocerias en cualquier lugar de la tierra?'),
('lovers', 1, 'What is a movie or show we are absolutely not allowed to watch without each other?', 'Cual es una pelicula o serie que absolutamente no podemos ver sin el otro?'),
('lovers', 1, 'What is the most flattering thing anyone has ever said to you about me?', 'Cual es la cosa mas halagadora que alguien te ha dicho sobre mi?'),
('lovers', 1, 'What is a habit of mine you started doing too, even though you would never admit it?', 'Cual es un habito mio que tu tambien empezaste a hacer, aunque nunca lo admitirias?'),
('lovers', 1, 'If we had to choose one outfit each of us is forced to wear for a year, what is mine and what is yours?', 'Si tuvieramos que elegir un atuendo que cada uno este obligado a usar por un ano, cual es el mio y cual es el tuyo?'),
('lovers', 1, 'What is your favorite tiny touch of mine that you would miss within ten minutes?', 'Cual es tu pequeno toque favorito mio que extranarias dentro de diez minutos?'),
('lovers', 1, 'If we hosted a podcast about being us, what would the first episode be called?', 'Si organizaramos un podcast sobre ser nosotros, como se llamaria el primer episodio?'),
('lovers', 1, 'What is a small flirt I do that still makes you feel like the only person in the room?', 'Cual es un pequeno coqueteo que hago que aun te hace sentir como la unica persona en la sala?'),
('lovers', 1, 'What is the most romantic spot in our home that has nothing to do with the bedroom?', 'Cual es el lugar mas romantico en nuestra casa que no tiene nada que ver con la habitacion?'),
('lovers', 1, 'What is the most embarrassing photo you have of me that you secretly love the most?', 'Cual es la foto mas vergonzosa que tienes de mi que en secreto mas amas?'),
('lovers', 1, 'If we had a holiday that was just ours, what would we celebrate and how?', 'Si tuvieramos un dia festivo que fuera solo nuestro, que celebrariamos y como?'),
('lovers', 1, 'What is the most beautiful boring evening with me you can imagine?', 'Cual es la noche mas hermosa y aburrida conmigo que puedas imaginar?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('lovers', 2, 'What is something you noticed me doing this week that made you fall a little harder?', 'Que me notaste haciendo esta semana que te hizo enamorarte un poco mas?'),
('lovers', 2, 'When did you first realize you wanted to know the boring parts of my day?', 'Cuando te diste cuenta por primera vez de que querias saber las partes aburridas de mi dia?'),
('lovers', 2, 'What is a way I show love that took you a while to learn how to receive?', 'Cual es una manera en que muestro amor que te tomo un tiempo aprender a recibir?'),
('lovers', 2, 'What is the kindest thing I have ever done for you that I do not even remember doing?', 'Cual es la cosa mas amable que he hecho por ti que ni siquiera recuerdo haber hecho?'),
('lovers', 2, 'When was the last time I made you laugh in a way that surprised you?', 'Cuando fue la ultima vez que te hice reir de una manera que te sorprendio?'),
('lovers', 2, 'What is a small thing about us that has quietly improved this year?', 'Cual es una pequena cosa sobre nosotros que ha mejorado silenciosamente este ano?'),
('lovers', 2, 'What is a way I look at you that you wish I knew you noticed?', 'Cual es una manera en que te miro que desearias que supiera que has notado?'),
('lovers', 2, 'What is something we do together that is so ordinary it has become sacred?', 'Que hacemos juntos que es tan ordinario que se ha vuelto sagrado?'),
('lovers', 2, 'When did you last realize you were genuinely proud to be with me?', 'Cuando te diste cuenta por ultima vez de que estabas genuinamente orgulloso de estar conmigo?'),
('lovers', 2, 'What is a part of me you find more beautiful now than the day you met me?', 'Que parte de mi encuentras mas hermosa ahora que el dia que me conociste?'),
('lovers', 2, 'What is something you have changed your mind about because of how I move through the world?', 'En que has cambiado de opinion debido a como me muevo por el mundo?'),
('lovers', 2, 'What is the most thoughtful thing I have done for you in the last month that you have not said thank you for yet?', 'Cual es la cosa mas considerada que he hecho por ti en el ultimo mes por la que aun no me has dado las gracias?'),
('lovers', 2, 'What is a sound I make that you secretly love more than I will ever know?', 'Que sonido hago que en secreto amas mas de lo que jamas sabre?'),
('lovers', 2, 'What is something you noticed about my body recently that you would compliment if you knew how?', 'Que notaste sobre mi cuerpo recientemente que cumplirias si supieras como?'),
('lovers', 2, 'What is a tiny tradition we have built that you would never want to outgrow?', 'Cual es una pequena tradicion que hemos construido de la que nunca querrias dejar atras?'),
('lovers', 2, 'What is a way I have changed since we met that you have quietly cheered for?', 'De que manera he cambiado desde que nos conocimos por la que has aplaudido en silencio?'),
('lovers', 2, 'When did you last feel turned on by something that had nothing to do with how I looked?', 'Cuando te sentiste por ultima vez excitado por algo que no tenia nada que ver con como me veia?'),
('lovers', 2, 'What is something I do that calms your nervous system in a way nothing else does?', 'Que hago que calma tu sistema nervioso de una manera que nada mas lo hace?'),
('lovers', 2, 'What is a memory from this past season of us you want to remember for a long time?', 'Que recuerdo de esta temporada pasada de nosotros quieres recordar por mucho tiempo?'),
('lovers', 2, 'What is a way I take care of you that you used to be embarrassed to need?', 'De que manera cuido de ti que solias estar avergonzado de necesitar?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('lovers', 3, 'When did you first feel safe enough with me to stop performing?', 'Cuando te sentiste lo suficientemente seguro conmigo por primera vez para dejar de actuar?'),
('lovers', 3, 'What is something hard about being loved by me that you have made peace with?', 'Que es algo dificil de ser amado por mi con lo que has hecho las paces?'),
('lovers', 3, 'What is something I do under stress that you would gently want me to know about?', 'Que hago bajo estres que gentilmente querrias que yo supiera?'),
('lovers', 3, 'What is a fear you have about us that you would feel relieved to put into words tonight?', 'Que miedo tienes sobre nosotros que sentirias alivio de poner en palabras esta noche?'),
('lovers', 3, 'When have I let you down in a way you have already forgiven but never told me about?', 'Cuando te he fallado de una manera que ya has perdonado pero nunca me has dicho?'),
('lovers', 3, 'What is something you have been quietly hoping for from this relationship lately?', 'Que has estado esperando silenciosamente de esta relacion ultimamente?'),
('lovers', 3, 'What is a way you wish I would show up for you more, said with love and not as a complaint?', 'De que manera desearias que yo me presentara para ti mas, dicho con amor y no como queja?'),
('lovers', 3, 'When did you last feel completely understood by me in a way that surprised you?', 'Cuando te sentiste por ultima vez completamente entendido por mi de una manera que te sorprendio?'),
('lovers', 3, 'What is something you used to need from a partner that you no longer need because of how you have grown?', 'Que solias necesitar de una pareja que ya no necesitas debido a como has crecido?'),
('lovers', 3, 'What is the version of yourself you most love being in our relationship?', 'Cual es la version de ti que mas amas ser en nuestra relacion?'),
('lovers', 3, 'When have I done something brave for us that you do not think I got enough credit for?', 'Cuando he hecho algo valiente por nosotros por lo que no creo que haya recibido suficiente credito?'),
('lovers', 3, 'What is a small way I have hurt you that I do not realize I do?', 'Cual es una pequena manera en que te he lastimado que no me doy cuenta que hago?'),
('lovers', 3, 'What is something you wish we made more space for in our life together?', 'Que desearias que hicieramos mas espacio en nuestra vida juntos?'),
('lovers', 3, 'When did you last feel proud of how we handled something hard as a team?', 'Cuando te sentiste por ultima vez orgulloso de como manejamos algo dificil como equipo?'),
('lovers', 3, 'What is a part of your past you have not told me about yet that you think you might be ready to?', 'Cual es una parte de tu pasado que aun no me has contado de la que crees que podrias estar listo?'),
('lovers', 3, 'What is something you have stopped expecting from love because of me?', 'Que has dejado de esperar del amor debido a mi?'),
('lovers', 3, 'When was the last time you held back a kindness toward me, and why?', 'Cuando fue la ultima vez que retuviste una amabilidad hacia mi, y por que?'),
('lovers', 3, 'What is a way I hold you that feels different from how anyone else ever has?', 'De que manera te abrazo que se siente diferente a como cualquier otro lo ha hecho?'),
('lovers', 3, 'What is a question you have wanted to ask me but have been waiting for the right night to ask?', 'Que pregunta has querido hacerme pero has estado esperando la noche adecuada para hacerla?'),
('lovers', 3, 'What is a moment between us that quietly shifted what you believed was possible in love?', 'Cual es un momento entre nosotros que silenciosamente cambio lo que creias posible en el amor?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('lovers', 4, 'What is the truth about how you have been doing that you have been protecting me from?', 'Cual es la verdad sobre como has estado que me has estado protegiendo de saber?'),
('lovers', 4, 'What is a way you have wanted me to want you that you have been afraid to ask for?', 'De que manera has querido que te deseara que has tenido miedo de pedir?'),
('lovers', 4, 'What is a fear about us that has been sitting quietly under your other thoughts lately?', 'Que miedo sobre nosotros ha estado sentado silenciosamente bajo tus otros pensamientos ultimamente?'),
('lovers', 4, 'What is something you have been needing emotionally that you have not figured out how to name?', 'Que has estado necesitando emocionalmente que no has descubierto como nombrar?'),
('lovers', 4, 'When have you felt lonely in this relationship, and what would have made you feel met?', 'Cuando te has sentido solo en esta relacion, y que te habria hecho sentir acompanado?'),
('lovers', 4, 'What is a story about your body and self-worth you wish I knew the full version of?', 'Cual es una historia sobre tu cuerpo y autoestima de la que desearias que yo supiera la version completa?'),
('lovers', 4, 'What is something you have been wanting from our intimacy that you have not asked for out loud?', 'Que has estado queriendo de nuestra intimidad que no has pedido en voz alta?'),
('lovers', 4, 'When did you last feel insecure about us, and what was actually underneath it?', 'Cuando te sentiste por ultima vez inseguro sobre nosotros, y que estaba realmente debajo de ello?'),
('lovers', 4, 'What is a version of yourself you have been hiding from me without meaning to?', 'Cual es una version de ti que has estado escondiendome sin querer?'),
('lovers', 4, 'What is a way you are afraid you are too much for me, and where did that fear start?', 'De que manera tienes miedo de ser demasiado para mi, y donde empezo ese miedo?'),
('lovers', 4, 'When have you been hurt by me in a way you tucked away instead of bringing to me?', 'Cuando te he lastimado de una manera que escondiste en lugar de traermelo?'),
('lovers', 4, 'What is something you wish I would touch more often that you have not asked me to?', 'Que desearias que tocara mas a menudo que no me has pedido?'),
('lovers', 4, 'What is the deepest fantasy about us that has nothing to do with sex?', 'Cual es la fantasia mas profunda sobre nosotros que no tiene nada que ver con el sexo?'),
('lovers', 4, 'What is a desire you have had for years that you have only recently felt brave enough to name?', 'Que deseo has tenido por anos que solo recientemente te has sentido lo suficientemente valiente para nombrar?'),
('lovers', 4, 'What is something you have been carrying about an old love that still quietly shapes how you receive mine?', 'Que has estado cargando sobre un amor viejo que aun forma silenciosamente como recibes el mio?'),
('lovers', 4, 'What is a way I have made you feel unsafe that you have not had words for yet?', 'De que manera te he hecho sentir inseguro para la que aun no has tenido palabras?'),
('lovers', 4, 'When have you imagined our breakup not because you wanted it but because you were trying to understand how much I mean to you?', 'Cuando has imaginado nuestra ruptura no porque la quisieras sino porque estabas tratando de entender cuanto significo para ti?'),
('lovers', 4, 'What is a piece of grief you carry from before me that still lives in this relationship?', 'Que pieza de dolor cargas de antes de mi que aun vive en esta relacion?'),
('lovers', 4, 'What is something you wish I would notice about your body that has nothing to do with how it looks?', 'Que desearias que yo notara sobre tu cuerpo que no tiene nada que ver con como se ve?'),
('lovers', 4, 'What is the most honest thing you have not told me about what you need right now?', 'Cual es la cosa mas honesta que no me has dicho sobre lo que necesitas ahora mismo?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('lovers', 5, 'When was the last time my touch caught you completely off guard, and what did it remind you of?', 'Cuando fue la ultima vez que mi toque te tomo completamente desprevenido, y de que te recordo?'),
('lovers', 5, 'What is the unspoken language our bodies have built together that no one else would recognize?', 'Cual es el lenguaje no dicho que nuestros cuerpos han construido juntos que nadie mas reconoceria?'),
('lovers', 5, 'What is the part of me you would memorize first if you ever had to live without me?', 'Cual es la parte de mi que memorizarias primero si alguna vez tuvieras que vivir sin mi?'),
('lovers', 5, 'What is the truest reason you keep choosing me, especially on the days it is not easy?', 'Cual es la razon mas verdadera por la que sigues eligiendome, especialmente en los dias que no es facil?'),
('lovers', 5, 'What is a way you want me when no one else is around that you have never described to me?', 'De que manera me quieres cuando nadie mas esta alrededor que nunca me has descrito?'),
('lovers', 5, 'What is a kind of love you stopped believing in before me that I quietly gave back to you?', 'Que tipo de amor dejaste de creer antes de mi que yo te devolvi silenciosamente?'),
('lovers', 5, 'What is something about the way I make love with you that you would carry into your next life?', 'Que es algo sobre la manera en que hago el amor contigo que llevarias a tu proxima vida?'),
('lovers', 5, 'What is a moment between our bodies that you replay when you are far away from me?', 'Cual es un momento entre nuestros cuerpos que repites cuando estas lejos de mi?'),
('lovers', 5, 'What is a love you lost before me that taught you how to love me better?', 'Que amor perdiste antes de mi que te enseno a amarme mejor?'),
('lovers', 5, 'What is the version of us at eighty that you most quietly hope we get to become?', 'Cual es la version de nosotros a los ochenta que mas silenciosamente esperas que lleguemos a ser?'),
('lovers', 5, 'What is something you would want me to know about how you really felt during the hardest year we have had?', 'Que es algo que querrias que yo supiera sobre como realmente te sentiste durante el ano mas dificil que hemos tenido?'),
('lovers', 5, 'What is the most tender thing your body has ever told mine without using a single word?', 'Cual es la cosa mas tierna que tu cuerpo le ha dicho al mio sin usar una sola palabra?'),
('lovers', 5, 'What is something you grieve about the life you would have had without me, even though you would not trade us?', 'Que lamentas sobre la vida que habrias tenido sin mi, aunque no nos cambiarias?'),
('lovers', 5, 'What is a kind of beauty in me you have witnessed that I have never seen in myself?', 'Que tipo de belleza en mi has presenciado que yo nunca he visto en mi mismo?'),
('lovers', 5, 'What is the most courageous thing you have done in this relationship that you have never named out loud?', 'Cual es la cosa mas valiente que has hecho en esta relacion que nunca has nombrado en voz alta?'),
('lovers', 5, 'What is a part of intimacy with me that you would mourn if we ever lost it?', 'Que parte de la intimidad conmigo lamentarias si alguna vez la perdieramos?'),
('lovers', 5, 'What is a confession about how you want to be loved that you only feel safe saying to me tonight?', 'Cual es una confesion sobre como quieres ser amado que solo te sientes seguro de decirme esta noche?'),
('lovers', 5, 'What is the moment in this relationship that has come closest to feeling like a small kind of religion?', 'Cual es el momento en esta relacion que ha estado mas cerca de sentirse como una pequena religion?'),
('lovers', 5, 'If you had to leave me a single sentence to carry through the rest of my life, what would you choose?', 'Si tuvieras que dejarme una sola oracion para llevar por el resto de mi vida, cual elegirias?'),
('lovers', 5, 'What is the truth about loving me that has surprised you most, even after all of this?', 'Cual es la verdad sobre amarme que mas te ha sorprendido, incluso despues de todo esto?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('coworkers', 1, 'What is the most chaotic Slack message thread you have witnessed in your career?', 'Cual es el hilo de mensajes mas caotico que has presenciado en tu carrera?'),
('coworkers', 1, 'What is the office snack you would absolutely fight someone over if it ran out?', 'Cual es el snack de la oficina por el que absolutamente pelearias con alguien si se acabara?'),
('coworkers', 1, 'What is the most ridiculous meeting title you have ever seen on your calendar?', 'Cual es el titulo de reunion mas ridiculo que hayas visto en tu calendario?'),
('coworkers', 1, 'If our team had a mascot, what bizarre creature would it be and why?', 'Si nuestro equipo tuviera una mascota, que criatura extrana seria y por que?'),
('coworkers', 1, 'What is your most absurd hot take about office coffee?', 'Cual es tu opinion mas absurda sobre el cafe de la oficina?'),
('coworkers', 1, 'What is the workplace habit you have that everyone else thinks is a personality trait?', 'Cual es el habito de trabajo que tienes que todos los demas piensan que es un rasgo de personalidad?'),
('coworkers', 1, 'If our team got stuck together in an elevator for an hour, who would be in charge first?', 'Si nuestro equipo se quedara atrapado en un elevador por una hora, quien estaria a cargo primero?'),
('coworkers', 1, 'What is the most overused phrase in our workplace that you have started saying ironically?', 'Cual es la frase mas usada en nuestro lugar de trabajo que has empezado a decir de manera ironica?'),
('coworkers', 1, 'If you could rename one of our meeting rooms after a movie, what is the name?', 'Si pudieras renombrar una de nuestras salas de reuniones segun una pelicula, cual es el nombre?'),
('coworkers', 1, 'What is the strangest piece of office decor you have spotted in someone is workspace?', 'Cual es la pieza mas extrana de decoracion de oficina que has visto en el espacio de trabajo de alguien?'),
('coworkers', 1, 'What is a small office ritual you secretly look forward to in the middle of a workday?', 'Cual es un pequeno ritual de oficina que en secreto esperas en medio de un dia de trabajo?'),
('coworkers', 1, 'What is a hill you would die on about how teams should communicate?', 'Cual es una opinion que defenderias hasta el final sobre como los equipos deberian comunicarse?'),
('coworkers', 1, 'What is the most useless piece of corporate training you have ever sat through?', 'Cual es la pieza mas inutil de capacitacion corporativa por la que has pasado?'),
('coworkers', 1, 'What is a tab you keep open during meetings that has nothing to do with the meeting?', 'Cual es una pestana que mantienes abierta durante las reuniones que no tiene nada que ver con la reunion?'),
('coworkers', 1, 'What is a stationery item you have a frankly unreasonable opinion about?', 'Cual es un articulo de oficina sobre el que tienes una opinion francamente irrazonable?'),
('coworkers', 1, 'If we had to give every coworker in this room a superlative, what is yours?', 'Si tuvieramos que dar a cada companero en esta sala un superlativo, cual es el tuyo?'),
('coworkers', 1, 'What is the most surprising hobby someone on our team has that you only recently learned?', 'Cual es el pasatiempo mas sorprendente que alguien en nuestro equipo tiene que solo recientemente has aprendido?'),
('coworkers', 1, 'What is the funniest typo you have ever sent in a professional message?', 'Cual es el typo mas chistoso que has enviado en un mensaje profesional?'),
('coworkers', 1, 'What is a productivity trick that genuinely works for you that you do not even mention to anyone?', 'Cual es un truco de productividad que genuinamente funciona para ti que ni siquiera mencionas a nadie?'),
('coworkers', 1, 'What is the most chaotic team outing or off-site memory you carry?', 'Cual es el recuerdo mas caotico de una salida o evento de equipo que cargas?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('coworkers', 2, 'What is something you appreciate about how someone on our team works that you have never told them?', 'Que aprecias sobre como trabaja alguien en nuestro equipo que nunca les has dicho?'),
('coworkers', 2, 'What is a skill you picked up at a previous job that you secretly still use every week?', 'Que habilidad adquiriste en un trabajo anterior que en secreto aun usas cada semana?'),
('coworkers', 2, 'When did you last feel like you really clicked with a colleague on something hard?', 'Cuando te sentiste por ultima vez que realmente conectaste con un colega en algo dificil?'),
('coworkers', 2, 'What is a working style of yours that took you years to figure out and own?', 'Cual es un estilo de trabajo tuyo que te tomo anos descubrir y abrazar?'),
('coworkers', 2, 'What is the most generous thing a coworker has ever done for you in your career?', 'Cual es la cosa mas generosa que un companero ha hecho por ti en tu carrera?'),
('coworkers', 2, 'What is something you used to think mattered at work that you no longer care about at all?', 'Que solias pensar que importaba en el trabajo que ya no te importa en absoluto?'),
('coworkers', 2, 'When did you last realize a coworker had taught you something important without trying to?', 'Cuando te diste cuenta por ultima vez de que un companero te habia ensenado algo importante sin intentarlo?'),
('coworkers', 2, 'What is a piece of feedback you got early in your career that still shapes how you work?', 'Cual es un consejo que recibiste temprano en tu carrera que aun forma como trabajas?'),
('coworkers', 2, 'What is something about your job you have grown to genuinely enjoy that surprised you?', 'Que es algo sobre tu trabajo que has llegado a disfrutar genuinamente que te sorprendio?'),
('coworkers', 2, 'When did you last feel proud of how you handled a workplace moment that nobody clapped for?', 'Cuando te sentiste por ultima vez orgulloso de como manejaste un momento en el trabajo por el que nadie aplaudio?'),
('coworkers', 2, 'What is a leadership quality you have noticed in someone on this team that you would love to learn from?', 'Cual es una cualidad de liderazgo que has notado en alguien en este equipo de la que te encantaria aprender?'),
('coworkers', 2, 'What is a small thing about our work culture that you would protect with everything if someone tried to change it?', 'Cual es una pequena cosa sobre nuestra cultura laboral que protegerias con todo si alguien tratara de cambiarla?'),
('coworkers', 2, 'What is a strength of yours at work that you used to be insecure about?', 'Cual es una fortaleza tuya en el trabajo de la que solias estar inseguro?'),
('coworkers', 2, 'What is a tiny moment with a coworker that made you feel like part of a team in a way that surprised you?', 'Cual es un pequeno momento con un companero que te hizo sentir parte de un equipo de una manera que te sorprendio?'),
('coworkers', 2, 'What is something you have changed your mind about regarding how teams should work?', 'En que has cambiado de opinion sobre como los equipos deberian funcionar?'),
('coworkers', 2, 'What is a way you have grown professionally in the past year that you have not given yourself credit for?', 'En que has crecido profesionalmente en el ultimo ano por lo que no te has dado credito?'),
('coworkers', 2, 'What is a small kindness someone on this team has shown you that meant more than they probably knew?', 'Cual es una pequena amabilidad que alguien en este equipo te ha mostrado que significo mas de lo que probablemente sabian?'),
('coworkers', 2, 'When was the last time a colleague made your workday meaningfully better with something small?', 'Cuando fue la ultima vez que un colega hizo tu dia de trabajo significativamente mejor con algo pequeno?'),
('coworkers', 2, 'What is something you have learned about yourself at work in the last year that surprised you?', 'Que has aprendido sobre ti mismo en el trabajo en el ultimo ano que te sorprendio?'),
('coworkers', 2, 'What is a moment with this team that you would actually want to put in a memory book?', 'Cual es un momento con este equipo que realmente querrias poner en un libro de recuerdos?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('coworkers', 3, 'What is the work skill you secretly take pride in but rarely get credit for?', 'Cual es la habilidad de trabajo de la que en secreto te enorgulleces pero rara vez recibes credito?'),
('coworkers', 3, 'When did you last fail at work in a way that ended up teaching you something you needed?', 'Cuando fallaste por ultima vez en el trabajo de una manera que termino ensenandote algo que necesitabas?'),
('coworkers', 3, 'What is a way you wish our team trusted each other more?', 'De que manera desearias que nuestro equipo confiara mas el uno en el otro?'),
('coworkers', 3, 'What is something you have been carrying alone at work that you wish you could share with someone here?', 'Que has estado cargando solo en el trabajo que desearias poder compartir con alguien aqui?'),
('coworkers', 3, 'When did you last feel really seen at work for who you are, not just what you do?', 'Cuando te sentiste por ultima vez realmente visto en el trabajo por quien eres, no solo por lo que haces?'),
('coworkers', 3, 'What is a moment in your career when you finally felt like you belonged in a room you had been doubting yourself in?', 'Cual es un momento en tu carrera cuando finalmente te sentiste como si pertenecieras a una sala en la que habias estado dudando de ti mismo?'),
('coworkers', 3, 'What is something hard about your role lately that you have not said out loud at work?', 'Que es algo dificil sobre tu rol ultimamente que no has dicho en voz alta en el trabajo?'),
('coworkers', 3, 'When have you watched a teammate grow this past year in a way that quietly inspired you?', 'Cuando has visto a un companero de equipo crecer en el ultimo ano de una manera que silenciosamente te inspiro?'),
('coworkers', 3, 'What is a way you wish you were managed or led that you have never quite asked for?', 'De que manera desearias ser gestionado o liderado que nunca has pedido del todo?'),
('coworkers', 3, 'What is something you have been working on personally that is making you a better colleague?', 'Que has estado trabajando personalmente que te esta haciendo un mejor colega?'),
('coworkers', 3, 'When did you last feel proud of how a coworker showed up for you when you really needed it?', 'Cuando te sentiste por ultima vez orgulloso de como un companero se presento para ti cuando realmente lo necesitabas?'),
('coworkers', 3, 'What is a way your relationship with work has changed in the last few years that you are still figuring out?', 'De que manera tu relacion con el trabajo ha cambiado en los ultimos anos que aun estas descubriendo?'),
('coworkers', 3, 'What is a piece of feedback you needed to hear years ago that nobody had the courage to give you?', 'Cual es un consejo que necesitabas escuchar hace anos que nadie tuvo el valor de darte?'),
('coworkers', 3, 'What is something a former coworker said about you that has stayed with you, good or hard?', 'Que es algo que un ex companero dijo sobre ti que se ha quedado contigo, bueno o dificil?'),
('coworkers', 3, 'What is a quality on this team you would put in the water if you could make it spread?', 'Cual es una cualidad en este equipo que pondrias en el agua si pudieras hacerla expandirse?'),
('coworkers', 3, 'When did you last advocate for someone at work who could not advocate for themselves?', 'Cuando defendiste por ultima vez a alguien en el trabajo que no podia defenderse a si mismo?'),
('coworkers', 3, 'What is a working part of yourself you have had to unlearn to actually grow?', 'Cual es una parte de trabajo de ti mismo que has tenido que desaprender para realmente crecer?'),
('coworkers', 3, 'What is a small wound from a previous workplace you still carry quietly into this one?', 'Cual es una pequena herida de un lugar de trabajo anterior que aun cargas silenciosamente a este?'),
('coworkers', 3, 'When did a coworker challenge you in a way that ended up making you better?', 'Cuando un companero te desafio de una manera que termino haciendote mejor?'),
('coworkers', 3, 'What is a hope you have for this team that you have never said out loud in a meeting?', 'Cual es una esperanza que tienes para este equipo que nunca has dicho en voz alta en una reunion?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('coworkers', 4, 'What is a part of you that you mostly leave at home before walking into work, and what would it be like to bring it in?', 'Cual es una parte de ti que en su mayoria dejas en casa antes de entrar al trabajo, y como seria traerla?'),
('coworkers', 4, 'When did you last feel like an imposter in a moment you should have been proud of?', 'Cuando te sentiste por ultima vez como un impostor en un momento del que deberias haber estado orgulloso?'),
('coworkers', 4, 'What is something you needed from a former boss or mentor that they never gave you?', 'Que necesitabas de un jefe o mentor anterior que nunca te dio?'),
('coworkers', 4, 'When have you been quietly grieving something about your career that you have not let yourself name?', 'Cuando has estado lamentando silenciosamente algo sobre tu carrera que no te has permitido nombrar?'),
('coworkers', 4, 'What is a part of work that costs you more than people realize?', 'Cual es una parte del trabajo que te cuesta mas de lo que la gente se da cuenta?'),
('coworkers', 4, 'What is a way you wish your work was seen that it currently is not?', 'De que manera desearias que tu trabajo fuera visto que actualmente no lo es?'),
('coworkers', 4, 'When have you held back from sharing an idea because you were afraid of how it would land?', 'Cuando te has contenido de compartir una idea porque tenias miedo de como caeria?'),
('coworkers', 4, 'What is a piece of ambition you have that you almost never let yourself say out loud?', 'Cual es una pieza de ambicion que tienes que casi nunca te permites decir en voz alta?'),
('coworkers', 4, 'What is something about your relationship to money or success you have only recently been honest with yourself about?', 'Que es algo sobre tu relacion con el dinero o el exito de lo que solo recientemente has sido honesto contigo mismo?'),
('coworkers', 4, 'When has a workplace dynamic made you feel small in a way that has lingered longer than it should have?', 'Cuando una dinamica del lugar de trabajo te ha hecho sentir pequeno de una manera que ha permanecido mas de lo que deberia haberlo hecho?'),
('coworkers', 4, 'What is a way you carry care for this team that nobody can really see from the outside?', 'De que manera cargas cuidado por este equipo que nadie puede realmente ver desde afuera?'),
('coworkers', 4, 'What is a fear you have about where your career is going that you have not told anyone close to you?', 'Cual es un miedo que tienes sobre a donde va tu carrera que no le has dicho a nadie cercano a ti?'),
('coworkers', 4, 'When did you last feel like you were the only one fighting for something at work that mattered?', 'Cuando te sentiste por ultima vez como si fueras el unico luchando por algo en el trabajo que importaba?'),
('coworkers', 4, 'What is something your work has taken from you that you are quietly trying to get back?', 'Que es algo que tu trabajo te ha quitado que estas tratando silenciosamente de recuperar?'),
('coworkers', 4, 'What is a piece of who you are at work that you wish more people knew about you?', 'Cual es una pieza de quien eres en el trabajo que desearias que mas personas supieran de ti?'),
('coworkers', 4, 'When did you last feel really lonely at work, and what was actually going on underneath?', 'Cuando te sentiste por ultima vez realmente solo en el trabajo, y que estaba realmente pasando por debajo?'),
('coworkers', 4, 'What is a trade-off you have made in your career that costs you more than you usually admit?', 'Cual es un sacrificio que has hecho en tu carrera que te cuesta mas de lo que normalmente admites?'),
('coworkers', 4, 'What is something you have wanted to say to a colleague but it has felt too vulnerable to lead with at work?', 'Que has querido decirle a un colega pero se ha sentido demasiado vulnerable para comenzar en el trabajo?'),
('coworkers', 4, 'When have you wanted to quit something at work and stayed anyway, and what was the real reason you stayed?', 'Cuando has querido renunciar a algo en el trabajo y te quedaste de todos modos, y cual fue la verdadera razon por la que te quedaste?'),
('coworkers', 4, 'What is the version of you at work that nobody here has really gotten to meet yet?', 'Cual es la version de ti en el trabajo que nadie aqui realmente ha llegado a conocer aun?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('coworkers', 5, 'What is the work moment that made you feel most alive, and what does it tell you about what you actually want?', 'Cual es el momento de trabajo que te hizo sentir mas vivo, y que te dice sobre lo que realmente quieres?'),
('coworkers', 5, 'What is a career regret you carry that, looking back, has shaped you more than the wins?', 'Cual es un arrepentimiento de carrera que cargas que, mirando hacia atras, te ha formado mas que las victorias?'),
('coworkers', 5, 'What is the legacy you want to leave on the people you have worked with, even if no one ever names it that way?', 'Cual es el legado que quieres dejar en las personas con las que has trabajado, aunque nadie lo nombre asi?'),
('coworkers', 5, 'What is something this work has cost you that you have decided was worth it, and what made it worth it?', 'Que es algo que este trabajo te ha costado que has decidido que valio la pena, y que lo hizo valer la pena?'),
('coworkers', 5, 'What is the truest reason you do the kind of work you do, beneath the resume version?', 'Cual es la razon mas verdadera por la que haces el tipo de trabajo que haces, debajo de la version del curriculum?'),
('coworkers', 5, 'When did you last feel like your work briefly meant something larger than itself?', 'Cuando te sentiste por ultima vez como si tu trabajo brevemente significara algo mas grande que el mismo?'),
('coworkers', 5, 'What is a part of yourself you would still be missing if you had never done this kind of work?', 'Cual es una parte de ti que aun te faltaria si nunca hubieras hecho este tipo de trabajo?'),
('coworkers', 5, 'What is a coworker from any point in your career whose memory you carry as a quiet kind of teacher?', 'Cual es un companero de cualquier punto de tu carrera cuyo recuerdo cargas como una especie silenciosa de maestro?'),
('coworkers', 5, 'What is something you used to want from work that you have outgrown without noticing?', 'Que solias querer del trabajo que has superado sin darte cuenta?'),
('coworkers', 5, 'When did you last witness a colleague do something at work that made you reconsider what excellence actually looks like?', 'Cuando presenciaste por ultima vez a un colega hacer algo en el trabajo que te hizo reconsiderar como se ve realmente la excelencia?'),
('coworkers', 5, 'What is the hardest professional season you have lived through, and what is the unexpected gift it left behind?', 'Cual es la temporada profesional mas dificil que has vivido, y cual es el regalo inesperado que dejo atras?'),
('coworkers', 5, 'What is a kind of work you would secretly love to be doing twenty years from now, even if it makes no sense yet?', 'Cual es un tipo de trabajo que en secreto te encantaria estar haciendo dentro de veinte anos, aunque aun no tenga sentido?'),
('coworkers', 5, 'What is the version of yourself you got to become because of this team specifically?', 'Cual es la version de ti que llegaste a ser debido a este equipo especificamente?'),
('coworkers', 5, 'When have you had to grieve a version of your career you thought you would have by now?', 'Cuando has tenido que lamentar una version de tu carrera que pensabas que tendrias para ahora?'),
('coworkers', 5, 'What is a quiet beautiful truth about work that nobody told you when you started?', 'Cual es una verdad silenciosa y hermosa sobre el trabajo que nadie te dijo cuando empezaste?'),
('coworkers', 5, 'What is something you would want a younger version of yourself to know about doing work that matters?', 'Que querrias que una version mas joven de ti supiera sobre hacer trabajo que importa?'),
('coworkers', 5, 'What is the bravest professional choice you have ever made that almost no one knows the full weight of?', 'Cual es la eleccion profesional mas valiente que has hecho de la que casi nadie sabe el peso completo?'),
('coworkers', 5, 'What is the most generous thing a colleague has ever done for you that quietly changed your life?', 'Cual es la cosa mas generosa que un colega ha hecho por ti que silenciosamente cambio tu vida?'),
('coworkers', 5, 'What is the work moment that broke your heart in a way that ended up making you better at what you do?', 'Cual es el momento de trabajo que te rompio el corazon de una manera que termino haciendote mejor en lo que haces?'),
('coworkers', 5, 'If this room is the only team you ever truly belonged to in your career, what would that have given you?', 'Si esta sala es el unico equipo al que verdaderamente perteneciste en tu carrera, que te habria dado?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('strangers', 1, 'What is the most interesting thing about today that almost no one knows?', 'Cual es la cosa mas interesante sobre hoy que casi nadie sabe?'),
('strangers', 1, 'If a movie made about your week so far had a title, what would it be?', 'Si una pelicula hecha sobre tu semana hasta ahora tuviera un titulo, cual seria?'),
('strangers', 1, 'What is the most surprising opinion you hold about something completely unimportant?', 'Cual es la opinion mas sorprendente que tienes sobre algo completamente sin importancia?'),
('strangers', 1, 'What is your weirdest food order that you swear is actually amazing?', 'Cual es tu pedido de comida mas raro del que juras que en realidad es increible?'),
('strangers', 1, 'If you had to teach a stranger one absolutely useless skill in five minutes, what is it?', 'Si tuvieras que ensenarle a un extrano una habilidad absolutamente inutil en cinco minutos, cual es?'),
('strangers', 1, 'What is the most dramatic thing that has happened to you in the last twenty four hours?', 'Cual es la cosa mas dramatica que te ha pasado en las ultimas veinticuatro horas?'),
('strangers', 1, 'What is a song that always lifts your mood within ten seconds?', 'Cual es una cancion que siempre te levanta el animo dentro de diez segundos?'),
('strangers', 1, 'What is something you have spent way too much time researching that you do not really need to know?', 'Que es algo en lo que has gastado demasiado tiempo investigando que no necesitas realmente saber?'),
('strangers', 1, 'If you were forced to give a TED talk tomorrow on something niche, what is the topic?', 'Si te obligaran a dar una charla TED manana sobre algo de nicho, cual es el tema?'),
('strangers', 1, 'What is a place you have been recently that you would secretly recommend to a stranger over a friend?', 'Cual es un lugar en el que has estado recientemente que en secreto recomendarias a un extrano antes que a un amigo?'),
('strangers', 1, 'What is the most charming small talk you have had with a stranger lately?', 'Cual es la conversacion ligera mas encantadora que has tenido con un extrano ultimamente?'),
('strangers', 1, 'If you got to pick a brand-new name just for this conversation, what is it?', 'Si pudieras elegir un nombre completamente nuevo solo para esta conversacion, cual es?'),
('strangers', 1, 'What is a habit of yours that strangers always seem to compliment you on?', 'Cual es un habito tuyo por el que los extranos siempre parecen halagarte?'),
('strangers', 1, 'What is the most interesting object in the room you can see right now and why?', 'Cual es el objeto mas interesante en la sala que puedes ver ahora mismo y por que?'),
('strangers', 1, 'What is a low-stakes opinion you would love to debate with a stranger right now?', 'Cual es una opinion de bajo riesgo que te encantaria debatir con un extrano ahora mismo?'),
('strangers', 1, 'If your entire personality had to be summarized in one tiny daily habit, what is it?', 'Si toda tu personalidad tuviera que resumirse en un pequeno habito diario, cual es?'),
('strangers', 1, 'What is the most surprising place you have ever found yourself enjoying being alone?', 'Cual es el lugar mas sorprendente en el que te has encontrado disfrutando estar solo?'),
('strangers', 1, 'What is something you have always been curious about asking a stranger but never have?', 'Que es algo que siempre has tenido curiosidad de preguntarle a un extrano pero nunca lo has hecho?'),
('strangers', 1, 'What is the best gift you have ever bought yourself just because?', 'Cual es el mejor regalo que te has comprado solo porque si?'),
('strangers', 1, 'What is something you do that would make total sense to your future self but baffles you now?', 'Que es algo que haces que tendria total sentido para tu yo futuro pero te desconcierta ahora?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('strangers', 2, 'What is a small detail about how you got to be in this room tonight that even you find a little funny?', 'Cual es un pequeno detalle sobre como llegaste a estar en esta sala esta noche que incluso tu encuentras un poco chistoso?'),
('strangers', 2, 'What is a piece of your story most people make wrong assumptions about?', 'Cual es una pieza de tu historia sobre la que la mayoria de la gente hace suposiciones equivocadas?'),
('strangers', 2, 'What is something you used to believe about who you would become that turned out completely differently?', 'Que solias creer sobre en quien te convertirias que resulto completamente diferente?'),
('strangers', 2, 'What is a moment in the past year you keep coming back to, even though it seems small?', 'Cual es un momento del ultimo ano al que sigues regresando, aunque parezca pequeno?'),
('strangers', 2, 'What is a piece of your life right now that you would love a stranger to be curious about?', 'Cual es una pieza de tu vida ahora mismo sobre la que te encantaria que un extrano tuviera curiosidad?'),
('strangers', 2, 'What is a hobby or interest you have grown into recently that genuinely makes you happy?', 'Cual es un pasatiempo o interes en el que has crecido recientemente que genuinamente te hace feliz?'),
('strangers', 2, 'When was the last time a stranger made your day better, and what did they do?', 'Cuando fue la ultima vez que un extrano mejoro tu dia, y que hicieron?'),
('strangers', 2, 'What is a part of how you grew up that you only recently understood was unusual?', 'Cual es una parte de como creciste que solo recientemente entendiste que era inusual?'),
('strangers', 2, 'What is a story about how you got your job, your home, or your name that you actually enjoy telling?', 'Cual es una historia sobre como obtuviste tu trabajo, tu hogar o tu nombre que realmente disfrutas contar?'),
('strangers', 2, 'What is a small thing you are quietly proud of about who you have become?', 'Cual es una pequena cosa de la que estas silenciosamente orgulloso sobre en quien te has convertido?'),
('strangers', 2, 'What is a city or place that lives in your memory more vividly than most places you have actually been?', 'Cual es una ciudad o lugar que vive en tu memoria mas vividamente que la mayoria de los lugares en los que has estado realmente?'),
('strangers', 2, 'What is a piece of how you spend your time that you think would surprise the people who think they know you?', 'Cual es una pieza de como pasas tu tiempo que crees que sorprenderia a las personas que piensan que te conocen?'),
('strangers', 2, 'What is a question you wish more strangers asked instead of where are you from?', 'Cual es una pregunta que desearias que mas extranos hicieran en lugar de de donde eres?'),
('strangers', 2, 'What is a small ambition of yours that nobody in your life knows about?', 'Cual es una pequena ambicion tuya de la que nadie en tu vida sabe?'),
('strangers', 2, 'What is the most beautiful thing a stranger ever said to you in passing?', 'Cual es la cosa mas hermosa que un extrano te ha dicho de pasada?'),
('strangers', 2, 'What is a tradition you have carried with you from a place you no longer live?', 'Cual es una tradicion que has llevado contigo de un lugar en el que ya no vives?'),
('strangers', 2, 'What is a story about your last name or first name that you have told way fewer times than people would guess?', 'Cual es una historia sobre tu apellido o primer nombre que has contado muchas menos veces de las que la gente adivinaria?'),
('strangers', 2, 'What is a part of your work or life that is more interesting than you usually let on at parties?', 'Cual es una parte de tu trabajo o vida que es mas interesante de lo que normalmente dejas entrever en las fiestas?'),
('strangers', 2, 'When did you last meet someone briefly who still pops into your head for no clear reason?', 'Cuando conociste por ultima vez a alguien brevemente que aun aparece en tu cabeza sin razon clara?'),
('strangers', 2, 'What is a small kindness from a stranger that you have never forgotten?', 'Cual es una pequena amabilidad de un extrano que nunca has olvidado?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('strangers', 3, 'What is something you carry with you that the people you meet rarely notice?', 'Que cargas contigo que las personas que conoces rara vez notan?'),
('strangers', 3, 'What is something you have been quietly thinking about for months that you have not said to anyone close to you?', 'Que has estado pensando silenciosamente por meses que no le has dicho a nadie cercano a ti?'),
('strangers', 3, 'What is a question about your life that even you have not finished answering?', 'Cual es una pregunta sobre tu vida que ni siquiera tu has terminado de responder?'),
('strangers', 3, 'When did you last feel completely understood by someone you had just met?', 'Cuando te sentiste por ultima vez completamente entendido por alguien que acababas de conocer?'),
('strangers', 3, 'What is a hard thing about your life right now that you would be relieved to say out loud to someone who does not know your full context?', 'Que es algo dificil sobre tu vida ahora mismo que sentirias alivio de decir en voz alta a alguien que no conoce tu contexto completo?'),
('strangers', 3, 'What is a kindness you have been wanting to give but have not figured out who to give it to yet?', 'Cual es una amabilidad que has querido dar pero aun no has descubierto a quien dar?'),
('strangers', 3, 'What is a way you have changed in the last few years that surprises even the people who think they know you?', 'En que has cambiado en los ultimos anos que sorprende incluso a las personas que piensan que te conocen?'),
('strangers', 3, 'When did you last cry for a reason you would actually be willing to explain?', 'Cuando lloraste por ultima vez por una razon que realmente estarias dispuesto a explicar?'),
('strangers', 3, 'What is something you have learned about loneliness that surprised you?', 'Que has aprendido sobre la soledad que te sorprendio?'),
('strangers', 3, 'What is something you are working on becoming better at that almost no one is rooting for because they do not know about it?', 'Que estas trabajando para ser mejor por lo que casi nadie esta animando porque no lo saben?'),
('strangers', 3, 'When was the last time you really listened to someone without already thinking about your response?', 'Cuando fue la ultima vez que realmente escuchaste a alguien sin ya estar pensando en tu respuesta?'),
('strangers', 3, 'What is a part of your life you wish someone would notice and say something kind about?', 'Cual es una parte de tu vida que desearias que alguien notara y dijera algo amable sobre ella?'),
('strangers', 3, 'What is something you have been forgiving yourself for lately?', 'Que has estado perdonandote ultimamente?'),
('strangers', 3, 'What is a question you have been afraid to ask the people closest to you?', 'Que pregunta has tenido miedo de hacerle a la gente mas cercana a ti?'),
('strangers', 3, 'When did you last feel really proud of who you are in a quiet, private way?', 'Cuando te sentiste por ultima vez realmente orgulloso de quien eres de una manera silenciosa y privada?'),
('strangers', 3, 'What is a moment from this year that quietly changed the direction you thought your life was going?', 'Cual es un momento de este ano que silenciosamente cambio la direccion en la que pensabas que iba tu vida?'),
('strangers', 3, 'What is something you used to chase that you finally stopped chasing this year, and how does that feel?', 'Que solias perseguir que finalmente dejaste de perseguir este ano, y como se siente eso?'),
('strangers', 3, 'When have you been gentle with yourself in a way that you used to think only weak people were?', 'Cuando has sido gentil contigo mismo de una manera que solias pensar que solo las personas debiles eran?'),
('strangers', 3, 'What is a kind of love you are still learning how to let yourself receive?', 'Cual es un tipo de amor que aun estas aprendiendo como permitirte recibir?'),
('strangers', 3, 'What is something true about your life right now that you wish someone would ask you about?', 'Que es algo verdadero sobre tu vida ahora mismo que desearias que alguien te preguntara?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('strangers', 4, 'What is something you would tell a stranger about your life that you would never tell a friend?', 'Que es algo que le dirias a un extrano sobre tu vida que nunca le dirias a un amigo?'),
('strangers', 4, 'What is the truth about how you have been doing lately, said with no one to manage feelings for?', 'Cual es la verdad sobre como has estado ultimamente, dicha sin nadie a quien gestionar sentimientos por?'),
('strangers', 4, 'What is something you have been pretending is fine that is actually a lot heavier than you let on?', 'Que has estado fingiendo que esta bien que en realidad es mucho mas pesado de lo que dejas ver?'),
('strangers', 4, 'When did you last feel like you were the only one in the room carrying what you were carrying?', 'Cuando te sentiste por ultima vez como si fueras el unico en la sala cargando lo que cargabas?'),
('strangers', 4, 'What is a secret about your life right now that would be easier to confess to someone you will never see again?', 'Cual es un secreto sobre tu vida ahora mismo que seria mas facil confesar a alguien que nunca volveras a ver?'),
('strangers', 4, 'What is the loneliest you have been recently, and what would have helped if someone had just noticed?', 'Cual es la mas solo que has estado recientemente, y que habria ayudado si alguien simplemente lo hubiera notado?'),
('strangers', 4, 'What is a part of your identity that you mostly keep quiet about, and what does it cost you to keep it quiet?', 'Cual es una parte de tu identidad que mayormente mantienes en silencio, y que te cuesta mantenerla en silencio?'),
('strangers', 4, 'What is a fear about your life that you have not let yourself fully feel yet?', 'Cual es un miedo sobre tu vida que aun no te has permitido sentir por completo?'),
('strangers', 4, 'What is a piece of grief you carry that you have never had a place to put down?', 'Que pieza de dolor cargas que nunca has tenido un lugar para dejar?'),
('strangers', 4, 'What is something about being a person that has felt heavier than you expected recently?', 'Que es algo sobre ser una persona que se ha sentido mas pesado de lo que esperabas recientemente?'),
('strangers', 4, 'What is something tender about your past that you do not usually trust people with?', 'Que es algo tierno sobre tu pasado del que no sueles confiar en la gente?'),
('strangers', 4, 'What is a way you have been disappointed by someone close to you that you have been quietly metabolizing alone?', 'De que manera has estado decepcionado por alguien cercano a ti que has estado metabolizando silenciosamente solo?'),
('strangers', 4, 'What is the version of yourself you are tired of performing?', 'Cual es la version de ti mismo de la que estas cansado de actuar?'),
('strangers', 4, 'What is something you wish someone would tell you tonight that you have been waiting to hear for a long time?', 'Que es algo que desearias que alguien te dijera esta noche que has estado esperando escuchar por mucho tiempo?'),
('strangers', 4, 'When have you wanted to be held by a stranger and known how strange it would sound to say so?', 'Cuando has querido que un extrano te abrazara y sabido lo extrano que sonaria decirlo?'),
('strangers', 4, 'What is a piece of your life that you wish someone outside of it could simply witness without trying to fix?', 'Cual es una pieza de tu vida que desearias que alguien fuera de ella pudiera simplemente presenciar sin intentar arreglar?'),
('strangers', 4, 'What is a story about your body or how you live in it that you almost never tell?', 'Cual es una historia sobre tu cuerpo o como vives en el que casi nunca cuentas?'),
('strangers', 4, 'When did you last want someone to ask you if you were really okay, and what would you have said?', 'Cuando quisiste por ultima vez que alguien te preguntara si realmente estabas bien, y que habrias dicho?'),
('strangers', 4, 'What is a sentence you have been wanting to say out loud for months that you could say tonight to someone who will not judge you for it?', 'Cual es una oracion que has querido decir en voz alta por meses que podrias decir esta noche a alguien que no te juzgara por ello?'),
('strangers', 4, 'What is something you are most afraid to be honest about with yourself right now?', 'Que es algo de lo que mas tienes miedo de ser honesto contigo mismo ahora mismo?');
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
('strangers', 5, 'What is the truth about your life right now that is easier to tell a stranger than the people you know?', 'Cual es la verdad sobre tu vida ahora mismo que es mas facil contarle a un extrano que a las personas que conoces?'),
('strangers', 5, 'What is a kind of love you stopped expecting to receive that you would still recognize the instant it arrived?', 'Que tipo de amor dejaste de esperar recibir que aun reconocerias en el instante que llegara?'),
('strangers', 5, 'What is the hardest year you have lived through, and what is the unexpected gift it left behind?', 'Cual es el ano mas dificil que has vivido, y cual es el regalo inesperado que dejo atras?'),
('strangers', 5, 'What is something you survived that you almost never tell anyone you survived?', 'Que es algo que sobreviviste que casi nunca le dices a nadie que sobreviviste?'),
('strangers', 5, 'What is the most beautiful thing about being a stranger to most people in this room that you would actually like to keep?', 'Cual es la cosa mas hermosa sobre ser un extrano para la mayoria de la gente en esta sala que en realidad te gustaria conservar?'),
('strangers', 5, 'What is the kindest version of yourself you have ever managed to be, and what was happening in your life when you were that person?', 'Cual es la version mas amable de ti mismo que has logrado ser, y que estaba pasando en tu vida cuando eras esa persona?'),
('strangers', 5, 'What is a part of your story that has hurt more than you let on, and what is the part of it that has quietly made you better?', 'Cual es una parte de tu historia que ha dolido mas de lo que dejas ver, y cual es la parte que silenciosamente te ha hecho mejor?'),
('strangers', 5, 'What is a piece of love you have carried for someone who could never carry it back, and how has it shaped you?', 'Cual es una pieza de amor que has cargado por alguien que nunca pudo cargarlo de vuelta, y como te ha formado?'),
('strangers', 5, 'What is the most important thing you have learned about being a person that you wish someone had told you earlier?', 'Cual es la cosa mas importante que has aprendido sobre ser una persona que desearias que alguien te hubiera dicho antes?'),
('strangers', 5, 'What is a quiet beautiful truth about your life right now that you have not had a place to say out loud yet?', 'Cual es una verdad silenciosa y hermosa sobre tu vida ahora mismo que aun no has tenido un lugar para decir en voz alta?'),
('strangers', 5, 'What is something you have been forgiven for that you have not yet fully forgiven yourself for?', 'Por que has sido perdonado que aun no te has perdonado completamente a ti mismo?'),
('strangers', 5, 'What is a goodbye from earlier in your life that quietly shapes the way you meet new people?', 'Cual es una despedida de antes en tu vida que silenciosamente forma la manera en que conoces a nuevas personas?'),
('strangers', 5, 'What is the most generous thing you have ever done for someone who will never know it was you?', 'Cual es la cosa mas generosa que has hecho por alguien que nunca sabra que eras tu?'),
('strangers', 5, 'What is something you are still hoping for that you have stopped saying out loud because saying it has hurt too many times?', 'Que es algo que aun esperas que has dejado de decir en voz alta porque decirlo ha dolido demasiadas veces?'),
('strangers', 5, 'What is a part of who you are now that you had to grieve becoming, and what was worth the grieving?', 'Cual es una parte de quien eres ahora que tuviste que lamentar convertirte, y que valio la pena lamentar?'),
('strangers', 5, 'What is the most honest thing you would want said about you at your funeral, even if it was a little hard to hear?', 'Cual es la cosa mas honesta que querrias que se dijera sobre ti en tu funeral, aunque fuera un poco dificil de escuchar?'),
('strangers', 5, 'What is the version of yourself you have quietly been becoming for years that almost no one has met yet?', 'Cual es la version de ti mismo en la que silenciosamente has estado convirtiendote por anos que casi nadie ha conocido aun?'),
('strangers', 5, 'What is a piece of wisdom you have earned that you would actually trust a stranger to carry away from this night?', 'Cual es una pieza de sabiduria que has ganado en la que realmente confiarias en que un extrano la llevara de esta noche?'),
('strangers', 5, 'What is the most beautiful thing a stranger could possibly say to you tonight that would land exactly where you need it?', 'Cual es la cosa mas hermosa que un extrano podria posiblemente decirte esta noche que aterrizaria exactamente donde la necesitas?'),
('strangers', 5, 'If we never see each other again after tonight, what is the one thing you would want to be remembered for by the strangers who briefly knew you?', 'Si nunca volvemos a vernos despues de esta noche, cual es la unica cosa por la que querrias ser recordado por los extranos que brevemente te conocieron?');
